-- Rolar's own technique catalog (no academy): bilingual, with "leads to" links. Admins edit it
-- in the app afterwards; ON CONFLICT keeps this safe if a technique by that name already exists.
INSERT INTO "techniques" ("id", "academy_id", "name", "name_en", "aliases", "category", "position", "description", "description_en") VALUES
  ('rolar-double-leg', NULL, 'Double leg', 'Double-leg takedown', ARRAY['Baiana', 'Queda de duas pernas']::text[], 'takedown', 'standing', 'Mude o nível baixando o quadril, dê o passo de penetração entre os pés do oponente, encaixe o ombro na cintura, abrace atrás dos joelhos e empurre na diagonal enquanto puxa as pernas.', 'Change levels by dropping your hips, take a penetration step between the opponent''s feet, put your shoulder on their hip, wrap behind the knees and drive diagonally while pulling the legs.'),
  ('rolar-single-leg', NULL, 'Single leg', 'Single-leg takedown', ARRAY['Baiana de uma perna']::text[], 'takedown', 'standing', 'Entre baixo com a cabeça por dentro, prenda uma perna do oponente junto ao peito e termine girando para o lado da perna presa ou puxando o pé para trás.', 'Shoot low with your head inside, trap one of the opponent''s legs against your chest and finish by turning towards the trapped leg or pulling the foot back.'),
  ('rolar-osoto-gari', NULL, 'O-soto-gari', 'Osoto gari', ARRAY['Grande ceifada externa', 'Major outer reap']::text[], 'takedown', 'standing', 'Desequilibre o oponente para trás e para o lado, avance ao lado dele e ceife a perna de apoio de trás para a frente com a sua perna.', 'Break the opponent''s balance back and to the side, step beside them and reap their supporting leg from behind with your leg.'),
  ('rolar-guard-pull', NULL, 'Puxar para a guarda', 'Guard pull', '{}'::text[], 'guard', 'standing', 'Com pegadas na gola e na manga, sente-se perto do oponente e coloque os pés no quadril dele ou feche a guarda, já puxando-o para baixo.', 'With collar and sleeve grips, sit down close to the opponent and put your feet on their hips or close your guard, pulling them down as you go.'),
  ('rolar-guillotine', NULL, 'Guilhotina', 'Guillotine choke', '{}'::text[], 'submission', 'standing', 'Envolva o pescoço com o braço por baixo do queixo, punho no esterno, segure a sua mão e puxe para cima enquanto afasta o quadril. Da guarda, feche as pernas e estique o corpo. No treino, aperte devagar.', 'Wrap the neck with your arm under the chin, wrist on the sternum, clasp your hands and pull up while moving your hips back. From guard, close your legs and stretch your body. In training, squeeze slowly.'),
  ('rolar-closed-guard', NULL, 'Guarda fechada', 'Closed guard', '{}'::text[], 'guard', 'closed_guard', 'Pernas cruzadas nas costas do oponente. Quebre a postura puxando a gola e a cabeça com os joelhos e trabalhe ângulos com o quadril.', 'Legs crossed behind the opponent''s back. Break their posture by pulling the collar and the head with your knees, and work angles with your hips.'),
  ('rolar-armbar-guard', NULL, 'Armlock da guarda', 'Armbar from guard', ARRAY['Chave de braço', 'Armbar']::text[], 'submission', 'closed_guard', 'Controle o braço com o polegar do oponente para cima, pé no quadril, gire 90°, passe a perna pela frente do rosto, feche os joelhos e eleve o quadril devagar.', 'Control the arm with the opponent''s thumb up, foot on the hip, pivot 90 degrees, bring your leg over the face, squeeze your knees and raise your hips slowly.'),
  ('rolar-triangle', NULL, 'Triângulo', 'Triangle choke', ARRAY['Triangle']::text[], 'submission', 'closed_guard', 'Com um braço do oponente dentro e outro fora, passe a perna por trás do pescoço, prenda-a atrás do joelho da outra perna, ajuste o ângulo e puxe a cabeça para baixo.', 'With one of the opponent''s arms in and one out, put your leg behind their neck, lock it behind your other knee, adjust the angle and pull the head down.'),
  ('rolar-kimura', NULL, 'Kimura', 'Kimura', ARRAY['Americana invertida', 'Double wristlock']::text[], 'submission', 'closed_guard', 'Segure o punho do oponente, passe o braço por cima do ombro dele e segure o seu próprio punho; gire o braço dele em direção às costas, sem trancos.', 'Grip the opponent''s wrist, bring your arm over their shoulder and grab your own wrist; rotate their arm towards their back, without jerking.'),
  ('rolar-hip-bump', NULL, 'Raspagem de quadril', 'Hip bump sweep', ARRAY['Sit-up sweep']::text[], 'sweep', 'closed_guard', 'Quando o oponente endireita a postura, sente-se, apoie a mão atrás, passe o braço por cima do ombro dele e empurre o quadril para cima e para o lado.', 'When the opponent straightens their posture, sit up, post your hand behind you, reach over their shoulder and drive your hips up and to the side.'),
  ('rolar-scissor-sweep', NULL, 'Raspagem tesoura', 'Scissor sweep', '{}'::text[], 'sweep', 'closed_guard', 'Abra a guarda, coloque a canela atravessada na barriga do oponente, puxe gola e manga e corte a perna de base dele enquanto puxa com a canela.', 'Open your guard, put your shin across the opponent''s belly, pull collar and sleeve and chop their base leg while pulling with your shin.'),
  ('rolar-omoplata', NULL, 'Omoplata', 'Omoplata', '{}'::text[], 'submission', 'closed_guard', 'Passe a perna por cima do ombro do oponente, gire para fora, sente-se, controle a cintura dele e incline o tronco para a frente devagar. Se ele rolar, siga para a montada ou o cem quilos.', 'Bring your leg over the opponent''s shoulder, turn out, sit up, control their waist and lean forward slowly. If they roll, follow to mount or side control.'),
  ('rolar-de-la-riva', NULL, 'Guarda De la Riva', 'De la Riva guard', ARRAY['DLR']::text[], 'guard', 'open_guard', 'Gancho por fora da perna da frente do oponente, pegada no tornozelo e na manga ou gola; use o gancho para desequilibrar.', 'Hook the outside of the opponent''s lead leg, grip the ankle and the sleeve or collar, and use the hook to off-balance them.'),
  ('rolar-berimbolo', NULL, 'Berimbolo', 'Berimbolo', '{}'::text[], 'sweep', 'open_guard', 'Da De la Riva, invista por baixo, role sobre o ombro e gire para chegar às costas do oponente.', 'From De la Riva, invert underneath, roll over your shoulder and spin to take the opponent''s back.'),
  ('rolar-butterfly-guard', NULL, 'Guarda borboleta', 'Butterfly guard', ARRAY['Butterfly']::text[], 'guard', 'open_guard', 'Sentado, com os dois pés como ganchos por dentro das coxas do oponente, controle por baixo do braço e mantenha o peito próximo.', 'Seated, with both feet hooked inside the opponent''s thighs, get an underhook and keep your chest close.'),
  ('rolar-butterfly-sweep', NULL, 'Raspagem de gancho', 'Butterfly sweep', ARRAY['Raspagem de borboleta']::text[], 'sweep', 'open_guard', 'Com underhook e pegada na manga, caia para o lado do braço preso e eleve a perna do oponente com o gancho.', 'With an underhook and a sleeve grip, fall to the side of the trapped arm and lift the opponent''s leg with your hook.'),
  ('rolar-spider-guard', NULL, 'Guarda aranha', 'Spider guard', ARRAY['Spider']::text[], 'guard', 'open_guard', 'Pegadas nas mangas e os pés nos bíceps do oponente; estique e encolha as pernas para controlar a distância.', 'Grip both sleeves and put your feet on the opponent''s biceps; extend and retract your legs to control distance.'),
  ('rolar-half-guard', NULL, 'Meia-guarda', 'Half guard', '{}'::text[], 'guard', 'half_guard', 'Prenda uma perna do oponente entre as suas, fique de lado, controle por baixo do braço (underhook) e não deixe o peito dele assentar.', 'Trap one of the opponent''s legs between yours, stay on your side, get the underhook and don''t let their chest settle on you.'),
  ('rolar-old-school-sweep', NULL, 'Raspagem old school', 'Old school sweep', '{}'::text[], 'sweep', 'half_guard', 'Da meia-guarda por baixo, com underhook, vá para baixo do oponente, segure o tornozelo da perna de base e empurre-o até sair por cima.', 'From bottom half guard with the underhook, come up under the opponent, grab the ankle of their base leg and drive through to come on top.'),
  ('rolar-toreando', NULL, 'Passagem toreando', 'Toreando pass', ARRAY['Toreando', 'Bullfighter pass']::text[], 'pass', 'open_guard', 'Segure as calças nos joelhos, empurre as pernas do oponente para um lado e circule para o outro, chegando ao cem quilos ou ao joelho na barriga.', 'Grip the pants at the knees, push the opponent''s legs to one side and circle to the other, landing in side control or knee on belly.'),
  ('rolar-knee-slice', NULL, 'Passagem de joelho', 'Knee slice pass', ARRAY['Knee slice', 'Knee cut']::text[], 'pass', 'half_guard', 'Atravesse a coxa do oponente com o joelho, controle a cabeça ou a gola com underhook e deslize o joelho até o chão do outro lado.', 'Cut your knee across the opponent''s thigh, control the head or the collar with an underhook and slide your knee to the mat on the other side.'),
  ('rolar-over-under', NULL, 'Passagem over-under', 'Over-under pass', '{}'::text[], 'pass', 'open_guard', 'Um braço por baixo de uma perna e o outro por cima da outra, ombro pesado na coxa; empilhe o quadril do oponente e caminhe para o lado.', 'One arm under one leg and the other over the other leg, heavy shoulder on the thigh; stack the opponent''s hips and walk around to the side.'),
  ('rolar-side-control', NULL, 'Cem quilos', 'Side control', ARRAY['Side mount']::text[], 'control', 'side_control', 'Peito no peito, quadril baixo, um braço controlando a cabeça e o outro o quadril; mantenha os joelhos junto ao corpo do oponente.', 'Chest to chest, hips low, one arm controlling the head and the other the hip; keep your knees tight to the opponent''s body.'),
  ('rolar-knee-on-belly', NULL, 'Joelho na barriga', 'Knee on belly', '{}'::text[], 'control', 'knee_on_belly', 'Joelho atravessado na barriga, a outra perna estendida e afastada, pegadas na gola e na calça; ajuste o peso quando o oponente se mexer.', 'Knee across the belly, other leg extended and wide, grips on collar and pants; adjust your weight as the opponent moves.'),
  ('rolar-mount', NULL, 'Montada', 'Mount', '{}'::text[], 'control', 'mount', 'Joelhos altos junto às axilas, pés por baixo do quadril do oponente e peso no peito dele; use as mãos para se equilibrar.', 'Knees high towards the armpits, feet under the opponent''s hips and weight on their chest; use your hands for balance.'),
  ('rolar-americana', NULL, 'Americana', 'Americana', ARRAY['Keylock']::text[], 'submission', 'side_control', 'Prenda o punho do oponente no chão com o cotovelo dobrado a 90°, passe o braço por baixo e segure o seu punho; deslize o punho dele em direção ao quadril e levante o cotovelo devagar.', 'Pin the opponent''s wrist to the mat with the elbow bent at 90 degrees, thread your arm underneath and grab your own wrist; slide their wrist towards the hip and lift the elbow slowly.'),
  ('rolar-armbar-mount', NULL, 'Armlock da montada', 'Armbar from mount', '{}'::text[], 'submission', 'mount', 'Da montada alta, prenda um braço junto ao peito, apoie a mão no chão, gire e passe a perna pela frente do rosto; feche os joelhos e eleve o quadril devagar.', 'From high mount, trap an arm against your chest, post your hand, pivot and swing your leg over the face; squeeze your knees and raise your hips slowly.'),
  ('rolar-cross-collar-choke', NULL, 'Estrangulamento cruzado', 'Cross collar choke', ARRAY['Gola cruzada']::text[], 'submission', 'mount', 'Primeira mão bem funda na gola, polegar por dentro; a segunda cruza por cima e segura a outra gola; abra os cotovelos e puxe.', 'First hand deep in the collar, thumb inside; the second crosses over and grips the other side; flare your elbows and pull.'),
  ('rolar-ezekiel', NULL, 'Ezequiel', 'Ezekiel choke', ARRAY['Ezekiel']::text[], 'submission', 'mount', 'Passe um braço por trás do pescoço do oponente e segure dentro da sua própria manga; com a outra mão, corte pela frente do pescoço e aperte.', 'Put one arm behind the opponent''s neck and grip inside your own sleeve; with the other hand, cut across the front of the neck and squeeze.'),
  ('rolar-back-control', NULL, 'Pegada nas costas', 'Back control', ARRAY['Costas', 'Back mount']::text[], 'control', 'back', 'Ganchos por dentro das coxas, pegada de cinto de segurança (seatbelt) e peito colado nas costas do oponente.', 'Hooks inside the thighs, seatbelt grip and chest glued to the opponent''s back.'),
  ('rolar-rear-naked-choke', NULL, 'Mata-leão', 'Rear naked choke', ARRAY['RNC']::text[], 'submission', 'back', 'Passe o braço por baixo do queixo, segure o bíceps do outro braço, coloque a outra mão atrás da cabeça e aperte fechando os cotovelos.', 'Slide your arm under the chin, grip the biceps of your other arm, put that hand behind the head and squeeze by bringing your elbows together.'),
  ('rolar-bow-and-arrow', NULL, 'Estrangulamento arco e flecha', 'Bow and arrow choke', '{}'::text[], 'submission', 'back', 'Das costas, segure a gola funda com uma mão, passe a outra para a calça do oponente, gire de lado, estique o corpo e puxe a gola.', 'From the back, grip deep in the collar with one hand, take the opponent''s pants with the other, turn to your side, extend your body and pull the collar.'),
  ('rolar-mount-escape', NULL, 'Saída de montada (upa)', 'Mount escape (bridge and roll)', ARRAY['Upa', 'Bridge and roll']::text[], 'escape', 'mount', 'Prenda o braço e o pé do mesmo lado do oponente, faça uma ponte forte por cima do seu ombro e role para cair na guarda dele.', 'Trap the opponent''s arm and foot on the same side, bridge hard over your shoulder and roll into their guard.'),
  ('rolar-elbow-knee-escape', NULL, 'Saída de cotovelo e joelho', 'Elbow-knee escape', ARRAY['Fuga de quadril', 'Shrimp escape']::text[], 'escape', 'mount', 'Faça fuga de quadril, use o cotovelo e o joelho para abrir espaço e recoloque a perna para recompor a meia-guarda ou a guarda.', 'Shrimp, use your elbow and knee to make space and bring your leg back in to recover half guard or guard.'),
  ('rolar-side-control-escape', NULL, 'Saída do cem quilos', 'Side control escape', '{}'::text[], 'escape', 'side_control', 'Antebraços como escudo no pescoço e no quadril do oponente, faça fuga de quadril para criar espaço e recoloque o joelho por dentro para voltar à guarda.', 'Frame with your forearms on the opponent''s neck and hip, shrimp to make space and bring your knee inside to recover guard.'),
  ('rolar-back-escape', NULL, 'Saída das costas', 'Back escape', '{}'::text[], 'escape', 'back', 'Proteja o pescoço com as duas mãos, deslize para o lado do braço de baixo, apoie as costas no chão e vire para dentro da guarda do oponente.', 'Protect your neck with both hands, slide to the side of the bottom arm, get your back to the mat and turn into the opponent''s guard.'),
  ('rolar-straight-ankle-lock', NULL, 'Chave de pé reta', 'Straight ankle lock', ARRAY['Botinha']::text[], 'submission', 'leg_entanglement', 'Prenda o pé do oponente sob a axila, antebraço por baixo do tendão de Aquiles, segure a sua lapela ou o punho e arqueie as costas devagar.', 'Trap the opponent''s foot under your armpit, forearm under the Achilles tendon, grip your lapel or wrist and arch your back slowly.')
ON CONFLICT DO NOTHING;--> statement-breakpoint
